import React, { useState } from 'react';
import Modal from 'react-modal';
import './App.css';
import 'bootstrap/dist/css/bootstrap.min.css';
import Navbar from './components/Navbar';
import Header from './components/Header';
import AboutMe from './components/AboutMe';
import Experience from './components/Experience';
import Portfolio from './components/Portfolio';
import Downloads from './components/Downloads';
import Contacts from './components/Contacts';
import Footer from './components/Footer';

Modal.setAppElement('#root'); // Set the root element for accessibility

function App() {
  const [showModal, setShowModal] = useState(true);
  const [showPortfolio, setShowPortfolio] = useState(false);

  const closeModal = () => {
    setShowModal(false);
  };

  const handleYesClick = () => {
    console.log('User clicked Yes');
    closeModal();
  };

  const handleNoClick = () => {
    console.log('User clicked No');
    setShowPortfolio(true);
    closeModal();
  };

  return (
    <>
      {showPortfolio && <Navbar />}
      {showPortfolio && <Header />}
      {showPortfolio && <AboutMe />}
      {showPortfolio && <Experience />}
      {showPortfolio && <Portfolio />}
      {showPortfolio && <Downloads />}
      {showPortfolio && <Contacts />}
      {showPortfolio && <Footer />}

      {/* Modal */}
      <Modal
        isOpen={showModal}
        onRequestClose={closeModal}
        contentLabel="Confirmation Modal"
        className="custom-modal"
      >
        <p></p>
        <div className="button-container">
          <button onClick={handleYesClick}>WORK</button>
          <button onClick={handleNoClick}>MUSIC</button>
        </div> 
      </Modal>
    </>
  );
}

export default App;
